<template>
  <el-dialog v-model="open" title="业务智能配置" width="min(1280px,96vw)" append-to-body class="business-config-dialog" :show-close="!busy" :close-on-click-modal="!busy" :close-on-press-escape="!busy">
    <div class="business-config">
      <section class="business-input">
        <el-select v-if="history.length" :model-value="plan?.id || ''" clearable placeholder="继续最近的业务方案" :disabled="busy" @change="resume"><el-option v-for="h in history" :key="h.id" :value="h.id" :label="h.summary"/></el-select>
        <label for="business-market">准备去哪里开展业务？</label>
        <el-input id="business-market" v-model="destination" :disabled="busy" maxlength="160" placeholder="例如：德国，面向当地个人销售家居用品" />
        <div class="business-material-label"><label for="business-material">业务材料</label><el-button link :disabled="busy" @click="fileInput.click()">添加文件</el-button><input ref="fileInput" type="file" accept=".txt,.csv,.docx,.pdf" hidden @change="readFile" /></div>
        <el-input id="business-material" v-model="materials" type="textarea" :rows="16" :disabled="busy" maxlength="30000" show-word-limit placeholder="粘贴业务介绍、收款说明、客户类型或数据处理材料，无需整理成规则。" />
        <span v-if="fileName" class="business-file">{{ fileName }}</span>
        <template v-if="plan?.questions?.length"><details class="business-questions" :open="plan.status==='clarification'"><summary>{{ plan.status==='clarification'?'还需要补充':'后续核查事项' }} · {{ plan.questions.length }}</summary><div v-for="q in plan.questions" :key="q.question"><strong>{{ q.question }}</strong><p>{{ q.reason }}{{ q.blocking?'':'（可先保存配置）' }}</p></div></details><label for="business-answers">补充说明</label><el-input id="business-answers" v-model="answers" type="textarea" :rows="4" :disabled="busy" maxlength="8000" placeholder="回答上面的关键问题" /></template>
        <el-button type="primary" title="使用已配置的DeepSeek服务分析材料；电话和邮箱会先隐藏" :loading="busy" :disabled="!canAnalyze" @click="analyze">{{ plan ? '重新分析并配置' : '分析业务并配置' }}</el-button>
        <p v-if="busy" role="status">正在阅读材料、核对业务范围并配置规则…</p>
      </section>
      <section class="business-output" aria-live="polite">
        <div v-if="!plan" class="business-empty"><h3>从业务材料到规则配置</h3><p>先识别你在做什么，再确定需要哪些检查。</p><ol><li>提取业务事实与原文依据</li><li>补充影响配置的关键信息</li><li>预览、试跑并保存整组规则</li></ol></div>
        <template v-else>
          <div class="business-summary"><span>{{ plan.destination }}</span><h3>{{ plan.summary }}</h3><p v-if="dirty" class="business-stale">输入已修改，请重新分析后再保存或试跑。</p></div>
          <dl class="business-facts"><div v-for="(f,i) in plan.facts" :key="i"><dt>{{ f.label }}</dt><dd>{{ f.value }}<details><summary>原文依据</summary><blockquote>{{ f.evidence }}</blockquote></details></dd></div></dl>
          <div v-if="plan.requirements.length" class="business-requirements"><h3>材料与人工核查</h3><div v-for="(r,i) in plan.requirements" :key="i"><strong>{{ r.name }}</strong><p>{{ r.reason }}</p></div></div>
          <div class="business-rule-heading"><h3>建议规则 · {{ plan.rules.length }}</h3><span>处理地区 {{ plan.region }}</span></div>
          <article v-for="r in plan.rules" :key="r.localId" class="business-rule">
            <div class="business-rule-title"><el-checkbox v-model="selected" :value="r.localId" :disabled="busy || !!savedIds.length || dirty">{{ r.name }}</el-checkbox><span>{{ kindLabel[r.kind] }}</span></div>
            <p>{{ r.reason }}</p><details><summary>条件与动作</summary><p>{{ r.summary }}</p><ul><li v-for="n in r.nodes.filter(n=>n.type==='action')" :key="n.id">{{ n.name }}：{{ n.config.message }}</li></ul><blockquote v-if="r.evidence">{{ r.evidence }}</blockquote><p v-if="r.sourceIds.length">参考：{{ r.sourceIds.join('、') }}</p></details>
            <p v-if="r.requiresConfirmation" class="business-confirm-condition">{{ r.summary }}<br/>{{ r.nodes.filter(n=>n.type==='action').map(n=>n.name+'：'+n.config.message).join('；') }}</p>
            <el-checkbox v-if="r.requiresConfirmation" v-model="confirmedRules" :value="r.localId" :disabled="busy || dirty || !!savedIds.length">我已核对这条规则的数值与处置条件</el-checkbox>
            <el-button link :disabled="busy || dirty" @click="emit('preview',r)">查看规则画布</el-button>
          </article>
          <details v-if="plan.references.length" class="business-references"><summary>参考资料与适用范围</summary><div v-for="r in plan.references" :key="r.id"><a :href="r.url" target="_blank" rel="noopener noreferrer">{{ r.title }}</a><p>{{ r.summary }}</p><span>核验：{{ r.checkedAt }}</span></div></details>
          <div class="business-actions" v-if="plan.status==='ready'"><el-button :disabled="busy || dirty || !plan.rules.length" @click="showSimulation=!showSimulation">{{ showSimulation?'收起试跑':'试跑样本' }}</el-button><el-button v-if="!savedIds.length" type="primary" :loading="saving" :disabled="busy || dirty || !selected.length" @click="save">保存 {{ selected.length }} 条规则</el-button><span v-else>已保存 {{ savedIds.length }} 条，待确认启用</span></div>
          <section v-if="showSimulation" class="business-simulation"><h3>样本试跑</h3><p>用你填写的示例，与材料齐全的示例对照。不是实际订单，不执行业务操作。</p><div class="business-sample-fields"><el-select v-model="sampleSource" :disabled="busy" aria-label="示例来源地区"><el-option v-for="r in ['CN','EU','UK','US','SEA','APAC','ME','AF','LATAM','OTHER']" :key="r" :value="r" :label="'来源 '+r"/></el-select><el-select v-model="sampleLevel" :disabled="busy" aria-label="示例数据级别"><el-option v-for="r in ['P1','P2','P3']" :key="r" :value="r" :label="r"/></el-select></div><div class="business-sample-fields"><el-input-number v-model="sampleAmount" :min="0" :max="1000000000000" :disabled="busy" aria-label="试跑金额"/><el-input v-model="sampleCurrency" maxlength="8" placeholder="币种，例如EUR" :disabled="busy" aria-label="试跑币种"/></div><div><el-checkbox v-model="sampleAuthorized" :disabled="busy">已登记处理依据</el-checkbox><el-checkbox v-model="sampleBasis" :disabled="busy">已登记传输依据</el-checkbox><el-checkbox v-model="sampleAssessment" :disabled="busy">已登记影响评估</el-checkbox></div><el-button :loading="simulating" :disabled="busy || dirty" @click="simulate">执行试跑</el-button><article v-for="r in simulation" :key="r.index"><strong>样本 {{ r.index }} · {{ r.passed?'规则校验通过':'需整改或复核' }}</strong><p v-for="(a,i) in r.actions" :key="i">{{ a.message || a.action }}</p></article></section>
          <p class="business-scope">{{ plan.scope }}</p>
        </template>
      </section>
    </div>
  </el-dialog>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {complianceApi} from '@/api'
const open=defineModel({type:Boolean,default:false}),emit=defineEmits(['preview','saved'])
const destination=ref(''),materials=ref(''),answers=ref(''),fileName=ref(''),fileInput=ref(null),plan=ref(null),selected=ref([]),confirmedRules=ref([]),savedIds=ref([]),analyzing=ref(false),uploading=ref(false),saving=ref(false),simulating=ref(false),snapshot=ref(''),showSimulation=ref(false),simulation=ref([])
const sampleSource=ref('CN'),sampleLevel=ref('P1')
const sampleAmount=ref(200),sampleCurrency=ref(''),sampleAuthorized=ref(false),sampleBasis=ref(false),sampleAssessment=ref(false)
const history=ref([])
watch(open,async value=>{if(value){try{history.value=await complianceApi.businessHistory()}catch{}}})
async function resume(id){if(!id||busy.value)return;analyzing.value=true;try{const r=await complianceApi.getBusinessPlan(id);destination.value=r.intake?.destination||r.destination;materials.value=r.intake?.materials||r.facts.map(f=>f.evidence).join('\n');answers.value=r.intake?.answers||'';plan.value=r;snapshot.value=fingerprint.value;selected.value=r.selectedLocalIds||r.rules.map(r=>r.localId);confirmedRules.value=r.confirmedRuleIds||[];savedIds.value=r.savedRuleIds||[];simulation.value=[];showSimulation.value=false;fileName.value='';sampleSource.value=r.marketRegion;sampleCurrency.value=r.rules.flatMap(r=>r.conditions||[]).find(c=>c.field==='currency'&&c.op==='eq')?.value||''}catch{}finally{analyzing.value=false}}
const kindLabel={business:'业务要求（待核对）',project:'建议策略',reference:'参考建议'}
const fingerprint=computed(()=>JSON.stringify([destination.value,materials.value,answers.value]))
watch([selected,sampleSource,sampleLevel,sampleAmount,sampleCurrency,sampleAuthorized,sampleBasis,sampleAssessment,fingerprint],()=>{simulation.value=[]},{deep:true})
const dirty=computed(()=>!!plan.value&&snapshot.value!==fingerprint.value)
const busy=computed(()=>analyzing.value||uploading.value||saving.value||simulating.value)
const canAnalyze=computed(()=>!busy.value&&destination.value.trim().length>0&&materials.value.trim().length>=8)
async function readFile(e){const file=e.target.files?.[0];e.target.value='';if(!file||busy.value)return;if(file.size>2*1024*1024){ElMessage.warning('文件不能超过2MB');return}uploading.value=true;try{const r=await complianceApi.extractBusiness(file);const value=materials.value+(materials.value?'\n\n':'')+r.text;if(value.length>30000){ElMessage.warning('合并材料超过30000字，请精简后重试');return}materials.value=value;fileName.value=file.name}catch{}finally{uploading.value=false}}
async function analyze(){if(!canAnalyze.value)return;analyzing.value=true;try{const result=await complianceApi.analyzeBusiness({materials:materials.value,destination:destination.value,answers:answers.value});plan.value=result;snapshot.value=fingerprint.value;selected.value=result.rules.map(r=>r.localId);confirmedRules.value=[];savedIds.value=result.savedRuleIds||[];simulation.value=[];showSimulation.value=false;sampleSource.value=result.marketRegion;sampleCurrency.value=result.rules.flatMap(r=>r.conditions).find(c=>c.field==='currency'&&c.op==='eq')?.value||''}catch{}finally{analyzing.value=false}}
async function save(){if(busy.value||dirty.value||!selected.value.length)return;if(plan.value.rules.some(r=>selected.value.includes(r.localId)&&r.requiresConfirmation&&!confirmedRules.value.includes(r.localId))){ElMessage.warning('请逐条核对数值和处置条件');return}try{await ElMessageBox.confirm('所选规则将保存为禁用状态。请确认业务事实、适用范围和建议条件；启用后会参与对应地区的数据处理核查。','确认规则配置',{confirmButtonText:'确认并保存',cancelButtonText:'返回检查'})}catch{return}if(dirty.value||busy.value)return;saving.value=true;try{const r=await complianceApi.applyBusiness(plan.value.id,selected.value,confirmedRules.value);savedIds.value=r.ruleIds;emit('saved');ElMessage.success('规则组已保存，确认后可在列表启用')}catch{}finally{saving.value=false}}
async function simulate(){if(busy.value||dirty.value)return;if(!sampleCurrency.value.trim()){ElMessage.warning('请填写示例币种');return}const base={targetRegion:plan.value.region,sourceRegion:sampleSource.value,dataLevel:sampleLevel.value,currency:sampleCurrency.value.trim().toUpperCase(),amount:sampleAmount.value,authorized:sampleAuthorized.value,hasScc:sampleBasis.value,hasDpia:sampleAssessment.value,crossBorder:plan.value.region!==sampleSource.value,customerIdPresent:true,quantity:1,lineCount:1,fieldCount:1,purpose:'交易风控'};const contexts=[base,{...base,authorized:true,hasScc:true,hasDpia:true}];simulating.value=true;try{const r=await complianceApi.simulateBusiness(plan.value.id,contexts,selected.value);simulation.value=r.results}catch{}finally{simulating.value=false}}

</script>
<style scoped>
.business-config{display:grid;grid-template-columns:minmax(300px,.9fr) minmax(0,1.1fr);gap:36px;height:68vh;color:#24343c}.business-input{display:flex;flex-direction:column;gap:12px;height:100%;overflow:auto;padding-right:12px;align-self:start}.business-input label{font-weight:600;font-size:14px}.business-material-label{display:flex;align-items:center;justify-content:space-between;margin-top:8px}.business-file{font-size:12px;color:#647782;overflow-wrap:anywhere}.business-input>.el-button{align-self:flex-start;margin-top:8px}.business-output{min-width:0;height:100%;overflow:auto;padding-right:12px;border-left:1px solid #e1e7eb;padding-left:32px}.business-config h3{font-size:17px;line-height:1.6;margin:0 0 12px}.business-config p{line-height:1.7;font-size:13px;margin:8px 0;color:#5e6d76}.business-empty{padding:60px 12px}.business-empty h3{font-size:26px;color:#1c3c55}.business-empty ol{font-size:14px;line-height:2.6;padding-left:20px;margin-top:28px}.business-summary>span{font-size:12px;color:#647782}.business-summary h3{font-size:17px;font-weight:500;margin-top:8px}.business-facts{margin:24px 0}.business-facts>div{display:grid;grid-template-columns:88px minmax(0,1fr);padding:14px 0;border-top:1px solid #e8edf0}.business-facts dt{font-size:12px;color:#697b87}.business-facts dd{margin:0;font-size:14px;overflow-wrap:anywhere}.business-output details{font-size:12px;color:#607582;margin-top:10px}.business-output summary{cursor:pointer;line-height:1.6}.business-output blockquote{margin:10px 0;border-left:2px solid #c5d6e4;padding:2px 12px;color:#61707b;white-space:pre-wrap;overflow-wrap:anywhere}.business-requirements,.business-questions{background:#f4f6f8;padding:20px;border-radius:12px;margin:12px 0 24px}.business-requirements>div+div,.business-questions>div+div{border-top:1px solid #dfe5e9;padding-top:14px;margin-top:14px}.business-questions strong,.business-requirements strong{font-size:13px}.business-rule-heading{display:flex;justify-content:space-between;gap:16px;align-items:baseline}.business-rule-heading>span,.business-rule-title>span{font-size:12px;color:#647782;font-weight:400}.business-rule{padding:18px 0;border-top:1px solid #e1e7eb}.business-rule-title{display:flex;gap:14px;justify-content:space-between;align-items:start}.business-rule-title :deep(.el-checkbox){height:auto;align-items:start;min-width:0}.business-rule-title :deep(.el-checkbox__label){white-space:normal;font-weight:600;line-height:1.6}.business-rule-title :deep(.el-checkbox__input){margin-top:4px}.business-rule-title>span{white-space:nowrap}.business-rule>p{margin-left:22px}.business-references{padding:16px 0;border-top:1px solid #e1e7eb}.business-references>div{margin:14px 0}.business-references a{color:#0071e3}.business-actions{display:flex;gap:12px;flex-wrap:wrap;padding:20px 0}.business-sample-fields{display:flex;gap:12px;margin:12px 0}.business-sample-fields>*{min-width:0;flex:1}.business-confirm-condition{padding:12px;background:#fff8eb;border-radius:8px;overflow-wrap:anywhere}.business-stale{color:#9b6100!important}.business-scope{font-size:12px!important;border-top:1px solid #e1e7eb;padding-top:16px}.business-simulation{padding:20px;background:#f5f7f9;border-radius:12px}.business-simulation>.el-button{margin:12px 0}.business-simulation article{padding:12px 0;border-top:1px solid #dfe5e9;font-size:13px}@media(max-width:800px){.business-config{grid-template-columns:1fr;gap:28px;height:auto}.business-input{height:auto;overflow:visible;padding-right:0}.business-output{height:auto;overflow:visible;padding-right:0}.business-output{border-left:0;border-top:1px solid #e1e7eb;padding:24px 0 0}.business-empty{padding:24px 0}.business-rule-title{flex-wrap:wrap}.business-facts>div{grid-template-columns:70px minmax(0,1fr)}}
</style>
<style>.business-config-dialog .el-dialog__body{max-height:78vh;overflow:hidden;padding-top:24px}.business-config-dialog .el-dialog__header{padding-bottom:16px;border-bottom:1px solid #e1e7eb}@media(max-width:800px){.business-config-dialog .el-dialog__body{overflow:auto}}</style>
